"""Stack-rewind helpers for applying a correction.

Pure functions that compute the clear-set and rebuilt dialogue stack the replay
drivers apply after a correction. They are variant-agnostic and side-effect free
(they return events / a new stack; the driver in :mod:`.executor` applies them).
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Dict, List, Optional

import structlog

from rasa.dialogue_understanding.stack.frames.dialogue_stack_frame import (
    DialogueStackFrame,
)
from rasa.dialogue_understanding.stack.frames.flow_stack_frame import (
    UserFlowStackFrame,
)
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.memory.manager import PROJECT_NAMESPACE
from rasa.mantle.state.provenance import read_provenance
from rasa.shared.core.events import is_memory_write_event

if TYPE_CHECKING:
    from rasa.dialogue_understanding.stack.dialogue_stack import DialogueStack
    from rasa.mantle.state.tracker_handle import TrackerHandle

structlogger = structlog.get_logger()


def slots_to_clear_after_rewind(
    tracker_handle: "TrackerHandle",
    anchor_position: int,
    frame_ids: set[str],
    keep_slots: set[str],
) -> List[str]:
    """Return slots produced by *frame_ids* after the rewind anchor, to clear.

    Clearing scope: only state the **rewound chain** produced *after* the anchor
    position. *frame_ids* is the set of frames being rewound — a single frame
    for a same-frame correction, or the ancestor(s) plus the re-entered
    sub-skill frame for a cross-skill re-entry.     This drops abandoned-branch
    derived state (e.g. a lock set on a branch the user left, or eligibility
    computed for the old sub-skill choice) while preserving values owned by
    frames *outside* the rewound chain — independent cross-skill identity a
    coarser "clear everything after" would wrongly discard. A true read-set
    dependency graph (clear only what depended on the corrected value) is the
    deferred, eval-gated precision upgrade.

    Ownership keys off each slot's **origin** (earliest producing frame), not its
    latest writer: a project-scoped value a sub-skill produced (e.g. the chosen
    card id) and an ancestor later merely *re-stamped* (an eligibility recompute
    re-writing the same id) still belongs to the sub-skill. Keying off the latest
    writer would let the re-stamp pull that still-valid cross-skill identity into
    the rewound frame's clear set and wrongly wipe it, forcing the customer to
    re-select an unchanged card.

    *keep_slots* (the corrected slots themselves, plus anything the correction's
    apply step just re-wrote) are never cleared. ``project.*`` slots are never
    cleared either: project memory stays set for the rest of the session even
    when a later hook write originated on the rewound frame.
    """
    latest_position: Dict[str, int] = {}
    origin_frame: Dict[str, Optional[str]] = {}
    order: List[str] = []
    for event in tracker_handle.tracker.events:
        if not is_memory_write_event(event):
            continue
        provenance = read_provenance(event)
        if provenance is None:
            continue
        if event.key not in latest_position:
            order.append(event.key)
            origin_frame[event.key] = provenance.frame_id
        latest_position[event.key] = provenance.position

    project_prefix = f"{PROJECT_NAMESPACE}."
    return [
        slot
        for slot in order
        if slot not in keep_slots
        and not slot.startswith(project_prefix)
        and origin_frame.get(slot) in frame_ids
        and latest_position[slot] > anchor_position
    ]


def reconstruct_stack_for_reentry(
    tracker_handle: "TrackerHandle",
    popped_frame_id: str,
    target_step_id: str,
) -> Optional["DialogueStack"]:
    """Return a stack that re-enters a completed sub-skill at *target_step_id*.

    Ported from v1's ``reset_stack_on_tracker_to_prior_state``, adapted to CALM
    v2 primitives. Finds the most recent historical stack state in which
    *popped_frame_id* was the top (active) frame, then rebuilds from that
    snapshot with the sub-skill frame's step pointer set back to
    *target_step_id*. Because the parent frame in that snapshot sits at its
    call-return step, this also rewinds the ancestor so its post-call steps
    re-run (re-evaluating routes, re-running replay-safe tools) for the
    corrected value once the re-entered sub-skill completes again.

    Unlike v1 there is no ``NEXT:`` continuation marker — Mantle re-walks from
    the literal ``step_id`` — and call frames are matched by their exact
    ``frame_id`` (carried on write-provenance) rather than ``frame_type``, since
    Mantle pushes calls as ``REGULAR`` frames. Returns ``None`` when no
    historical state had that frame on top (e.g. a value prefilled without the
    sub-skill ever executing), leaving the caller to apply the value only.
    """
    previous_stack_states = getattr(
        tracker_handle.tracker, "previous_stack_states", None
    )
    if previous_stack_states is None:
        return None

    reference: Optional["DialogueStack"] = None
    for snapshot in previous_stack_states():
        frames = snapshot.frames
        if frames and getattr(frames[-1], "frame_id", None) == popped_frame_id:
            reference = snapshot

    if reference is None:
        structlogger.debug(
            "mantle.correction.reentry_no_reference_snapshot",
            popped_frame_id=popped_frame_id,
            target_step_id=target_step_id,
        )
        return None

    structlogger.debug(
        "mantle.correction.reentry_reference_found",
        popped_frame_id=popped_frame_id,
        target_step_id=target_step_id,
        reference_frames=[
            (
                getattr(frame, "skill_id", None) or getattr(frame, "flow_id", None),
                getattr(frame, "step_id", None),
            )
            for frame in reference.frames
        ],
    )
    new_stack = reference.copy()
    frames = new_stack.frames
    for index, frame in enumerate(frames):
        if getattr(frame, "frame_id", None) == popped_frame_id:
            frames[index] = _frame_at_step(frame, target_step_id)
            break
    new_stack.frames = frames
    return new_stack


def _frame_at_step(
    frame: DialogueStackFrame, target_step_id: str
) -> DialogueStackFrame:
    """Return a copy of *frame* repositioned to *target_step_id* when it has one.

    Skill frames have no persisted step cursor; they are copied as the same
    class. ``previous_frame_type`` is preserved so parked CALL / interrupt
    identity survives rewind and re-entry.
    """
    if isinstance(frame, OrderedBlockStackFrame):
        return OrderedBlockStackFrame(
            frame_id=frame.frame_id,
            skill_id=frame.skill_id,
            block_id=frame.block_id,
            step_id=target_step_id,
            frame_type=frame.frame_type,
            previous_frame_type=frame.previous_frame_type,
        )
    if isinstance(frame, SkillStackFrame):
        return SkillStackFrame(
            frame_id=frame.frame_id,
            skill_id=frame.skill_id,
            frame_type=frame.frame_type,
            previous_frame_type=frame.previous_frame_type,
        )
    if isinstance(frame, UserFlowStackFrame):
        return UserFlowStackFrame(
            frame_id=frame.frame_id,
            flow_id=frame.flow_id,
            step_id=target_step_id,
            skill_id=frame.skill_id,
            frame_type=frame.frame_type,
            previous_frame_type=frame.previous_frame_type,
            suspended_agent_frames=frame.suspended_agent_frames,
        )
    return frame


def build_rewound_stack(
    tracker_handle: "TrackerHandle", target_frame_id: str, target_step_id: str
) -> Optional["DialogueStack"]:
    """Return a new stack with *target_frame_id* repositioned to *target_step_id*.

    The target frame's step pointer is moved back to the corrected step so the
    next ``advance_steps`` re-walks the flow forward from there (re-evaluating
    routes, re-running replay-safe tools, re-asking cleared collects). Frames
    above the target — unfinished work started after the corrected step — are
    dropped so the rewound flow drives again. Returns ``None`` when the target
    frame is not on the current stack (e.g. a sub-skill that already completed —
    handled by the cross-skill path, not this driver).
    """
    new_stack = tracker_handle.stack.copy()
    frames = new_stack.frames
    target_index = next(
        (
            i
            for i, frame in enumerate(frames)
            if getattr(frame, "frame_id", None) == target_frame_id
        ),
        None,
    )
    if target_index is None:
        return None

    kept = frames[: target_index + 1]
    kept[-1] = _frame_at_step(kept[-1], target_step_id)
    new_stack.frames = kept
    return new_stack
